[Form]
public class METARRecentErrorRuns extends FormRun
{
    QueryBuildRange executionDateFilterRange;

}

        /// <summary>
        /// Initialize DMFExecution data source
        /// </summary>
        public void init()
        {
            const str AR02 = "@MET:ConstStrArr";
            const str AR03 = "@MET:ConstArr";
            const str AR20 = "@MET:CostArr";
            const str AR67 = "@MET:ContAr";
            
            super();

            this.queryBuildDataSource().addOrderByField(fieldNum(DMFExecution, CreatedDateTime), SortOrder::Descending);

            executionDateFilterRange = SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(DMFExecution, CreatedDateTime));

            // MPJ_43843_ARDashboard
            // Filter by 4 interfaces AR-02 , AR-03, AR-20 and AR-67
            QueryBuildRange queryBuildRangeDefinitionGroup = SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(DMFExecution, DefinitionGroup));
            queryBuildRangeDefinitionGroup.value(AR02);
            
            queryBuildRangeDefinitionGroup = this.queryBuildDataSource().addRange(fieldNum(DMFExecution, DefinitionGroup));
            queryBuildRangeDefinitionGroup.value(AR03);

            queryBuildRangeDefinitionGroup = this.queryBuildDataSource().addRange(fieldNum(DMFExecution, DefinitionGroup));
            queryBuildRangeDefinitionGroup.value(AR20);

            queryBuildRangeDefinitionGroup = this.queryBuildDataSource().addRange(fieldNum(DMFExecution, DefinitionGroup));
            queryBuildRangeDefinitionGroup.value(AR67);

            // add existsJoin on DMFDefinitionGroupExecution
            QueryBuildDataSource qbdsExecutionError = this.queryBuildDataSource().addDataSource(tableNum(DMFDefinitionGroupExecution));
            qbdsExecutionError.joinMode(JoinMode::ExistsJoin);
            qbdsExecutionError.fetchMode(QueryFetchMode::One2One);
            qbdsExecutionError.addLink(fieldnum(DMFExecution, ExecutionId), fieldNum(DMFDefinitionGroupExecution, ExecutionId));

            // filtered by target status error or not run
            QueryBuildRange queryBuildRange = qbdsExecutionError.addRange(fieldNum(DMFDefinitionGroupExecution, TargetStatus));
            queryBuildRange.value(queryValue(DMFBatchJobStatus::Error));
            
            queryBuildRange = qbdsExecutionError.addRange(fieldNum(DMFDefinitionGroupExecution, TargetStatus));
            queryBuildRange.value(queryValue(DMFBatchJobStatus::NotRun));

        }

/// <summary>
/// display method To showFieldAccessException the status of
/// entity after file import and mapping are completed
/// </summary>
/// <param name = "_dmfDefinitionEntity">DMFDefinitionGroupEntity buffer</param>
/// <returns>Image container</returns>
public display container executionTargetStatus(DMFExecution _dmfExecution)
{
    DMFExecutionSummaryStatus summaryStatus = _dmfExecution.GetExecutionSummaryStatus();
    return DMFExecutionStatusHelper::GetExecutionSummaryStatusImageReference(summaryStatus);
}

        /// <summary>
        /// Display the execution company context
        /// </summary>
        public display str executionCompany(DMFExecution _dmfExecution)
        {
            DMFDefinitionGroupExecution definitionGroupExecution;

            select firstonly1 Company, EndDateTime, ReRun, ExecutionId from definitionGroupExecution
                order by definitionGroupExecution.EndDateTime desc where
                definitionGroupExecution.ExecutionId == _dmfExecution.ExecutionId;
            return definitionGroupExecution ? definitionGroupExecution.Company : '';
        }

        public void executeQuery()
        {
            utcdatetime filterDateTime;
            if(ExecutionDateRangeFilter.selection() == DMFExecutionHistoryDateFilterOptions::All)
            {
                executionDateFilterRange.value(SysQuery::valueUnlimited());
            }
            else
            {
                switch(ExecutionDateRangeFilter.selection())
                {
                    case DMFExecutionHistoryDateFilterOptions::PastDay:
                        filterDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -1);
                        break;

                    case DMFExecutionHistoryDateFilterOptions::Past3Days:
                        filterDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -3);
                        break;

                    case DMFExecutionHistoryDateFilterOptions::PastWeek:
                        filterDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -7);
                        break;

                    case DMFExecutionHistoryDateFilterOptions::PastMonth:
                        filterDateTime = DateTimeUtil::addMonths(DateTimeUtil::utcNow(), -1);
                        break;

                    case DMFExecutionHistoryDateFilterOptions::Past3Months:
                        filterDateTime = DateTimeUtil::addMonths(DateTimeUtil::utcNow(), -3);
                        break;

                    case DMFExecutionHistoryDateFilterOptions::Past6Months:
                        filterDateTime = DateTimeUtil::addMonths(DateTimeUtil::utcNow(), -6);
                        break;
                    
                }
                executionDateFilterRange.value(strFmt(' > %1', datetime2Str(filterDateTime)));
            }

            super();
        }

public boolean modified()
{
    boolean ret;
    
    ret = super();
    if(ret)
    {
        //Execute query
        DMFExecution_DS.executeQuery();
    }
    
    return ret;
}

        /// <summary>
        /// Navigate to execution summary workspace
        /// </summary>
        public void jumpRef()
        {
            super();

            Args args = new Args();
            args.caller(this.formRun());
            args.record(DMFExecution);

            // Navigate to the execution history workspace.
            new MenuFunction(MenuItemDisplayStr(DMFExecutionHistoryWorkspace), MenuItemType::Display).run(args);
        }

        /// <summary>
        /// Load data project
        /// </summary>
        public void jumpRef()
        {
            super();

            Args args = new Args();
            args.caller(this.formRun());
            args.record(DMFDefinitionGroup::find(this.valueStr()));

            // Load the data project.
            new MenuFunction(MenuItemDisplayStr(DMFQuickImport), MenuItemType::Display).run(args);

        }
